    "question": "次の英文は、人々の意見の分極化に関する文献の一部である（一部省略又は変更している箇所がある。）。Ａ～Ｄに当てはまるものの組合せとして最も妥当なのはどれか。なお、文中の■については設問の都合上伏せてある。\n\nThe term “group polarization” refers to something simple: after deliberation, people are likely to move toward a more ■ point in the direction to which the group’s members were originally inclined.\n\nFor an initial glimpse of the problem, let us consider a small experiment in democracy that was held in Colorado in 2005. About sixty US citizens were brought together and assembled into ten groups, each consisting of six people. Members of each group were asked to ［Ａ］ on the most controversial issue of the day: Should employers engage in “affirmative action” by giving a preference to members of traditionally disadvantaged groups?\n\nAs the experiment was designed, the groups consisted of “liberal” and “conservative” members―five groups whose members initially tended toward liberal positions on the issue, and five whose members tended toward conservative positions on the issue. People were asked to state their opinions individually and anonymously both before and after fifteen minutes of ［Ｂ］ . What was the effect of it?\n\nThe results were simple. In almost every group, members ended up with more ■ positions. Mildly favorable toward affirmative action before, liberals became ［Ｃ］ favorable toward it. Firmly negative about affirmative action before, conservatives became even ［Ｄ］ negative about it afterward.",
