      "エ": "S．ハンチントンは、国際的相互依存が進展した世界では、国家が持つパワーの源泉として伝統的な軍事力だけではなく経済的相互依存関係の非対称性も重要であるとした。そして、相互依存関係を断ち切られた場合、それを回復するためにかかる費用の程度を示す概念として敏感性を提示し、敏感性の高い国は低い国に対してパワーを発揮することができるとした。",
