    "question": "国際経済と開発に関するア～エの記述のうち、妥当なもののみを全て挙げているのはどれか。\n\nア．1961年、自由主義経済の発展のために協力を行う機構として経済協力開発機構（OECD）が設立され、欧米諸国のほか、日本、韓国が原加盟国として参加した。OECD は、加盟国の経済分野の課題解決のための活動を行っており、毎年OECD 経済見通しを発表している。2023年の見通しでは、新型コロナウイルス感染症の経済的影響が依然強く、世界全体の経済成長率（実質GDP 成長率）は過去最低の1 ％台になると発表された。\nイ．経済連携協定（EPA）は、幅広い経済関係の強化を目指して貿易や投資の自由化を進める協定である。我が国は世界に先駆けてEPA を推進してきたが、EPA は知的財産権の保護を対象外としているため、締結に消極的な国や地域が多く、1990年代以降、自由貿易協定（FTA）とともに締結数は減少傾向である。2018年、米国を含む11か国により、知的財産権の保護を含むサービス貿易や投資の自由化等を目的として、より包括的な経済連携協定であるCPTPPが締結された。\nウ．ミレニアム開発目標（MDGs）の後継である持続可能な開発目標（SDGs）とは、2015年の国連サミットにおいて全会一致で採択された、2030年までに持続可能でよりよい世界を目指す国際目標である。2030年を達成期限とし、貧困の撲滅や環境保全などの分野について17のゴールと169のターゲットなどから構成されている。2023年9月、国連本部において4年に1度となるSDG サミットが開催され、我が国のSDGs 達成に向けた取組について発信がなされた。\nエ．我が国の政府開発援助（ODA）については、従来から保健や教育など各国際機関が有する専門性を活用した国際機関を通じた援助の割合が高く、2021年の我が国のODA 実績（贈与相当額）の内訳は、国際機関を通じた援助が8割以上、二国間援助は2割未満となっている。また、我が国のODA 実績（支出純額及び贈与相当額）は1990年代以降一貫して、米国に次ぐ世界第2位であり、ODA を通じて相手国などとの関係強化を図っている。",
