    "question": "次のア、イ、ウは、国際関係の理論や概念を説明した文章の一部である（一部省略又は変更している箇所がある。）。それぞれの文章と、そこで説明されている理論・概念の組合せとして最も妥当なのはどれか。\n\nア．Even if the states can locate a deal that they prefer over war today, the state that is getting stronger will face a strong temptation to use its future power to try to revise the deal later. Unless there is some way for the growing state to make a credible commitment not to do that, then its adversary may decide that it is better to gamble on war today in order to stop or slow the anticipated shift.\nイ．Alliances are most commonly viewed as a response to threats. When entering an alliance, states will ally with the state that poses the major threat. The belief that states will tend to ally with rather than against the dominant side is surprisingly common. States are attracted to strength. The more powerful you are and the more clearly this is demonstrated, the more likely others are to ally with you.\nウ．Human actors are imagined to follow rules that associate particular identities to particular situations. Action involves evoking an identity or role and matching the obligations of that identity or role to a specific situation. The pursuit of purpose is associated with identities more than with interests, and with the selection of rules more than with individual rational expectations.",
