      "オ": "令和3（2021）年にデジタル社会の形成を目的としてデジタル庁が総務省の外局として、令和5（2023）年にこどもや若者が健やかに成長することのできる社会の実現を目的としてこども家庭庁が文部科学省の外局として、それぞれ設置された。両庁の長であるデジタル監と内閣府特命担当大臣は、府省横断的な課題に対応するため、関係行政機関の長に対して勧告することが可能であり、関係行政機関の長は、その勧告の内容を遵守することと規定されている。"
