      "イ": "真渕勝は、第二次世界大戦後の日本の官僚について、三つの類型を提示した。吏員型は、政治家の決定に忠実に従い政策を実施する官僚像である。調整型は、政治とは一線を画し政府内の省庁間調整を主たる役割とする官僚像である。国士型は、政治家や利益集団に対して超越的に振る舞う官僚像である。真渕によれば、終戦直後は吏員型の官僚が主流で、1970年代以降に調整型の官僚が登場したが、他方、国士型はこれまでほとんど見られなかったという。",
