      "イ": "日本における政策評価の導入は、国に先行する形で地方公共団体から始まった。三重県の事務事業評価はその代表的な例である。国レベルでは平成13（2001）年に政策評価法が制定され、各府省が政策評価を実施するようになった。同年の中央省庁再編により総務省に行政評価局が設置され、各府省の実施する政策評価の点検などを行っている。",
