      "オ": "近年、国と地方公共団体の双方において、EBPM の取組が進められている。EBPM とは、Evidence-based Public Management の略称で、証拠に基づく公共経営のことである。EBPMでは、科学的な証拠やデータに基づいて政策を選択することが目指されている。ナッジはEBPMの代表例であり、政策の対象を実験群と統制群の二つのグループにランダムに振り分けて政策の効果を検証するものである。"
