    "question": "次の英文は、国連難民高等弁務官事務所（UNHCR）が2023年に発表したGlobal Trends Report 2022に関する記述である（一部省略又は変更している箇所がある。）。この報告書に関するア～エの記述のうち、妥当なもののみを挙げているのはどれか。\n\nIn 2022, the number of people forcibly displaced by persecution, conflict, violence, human rights violations and events seriously disturbing public order grew by 21 per cent standing at an estimated 108.4 million at the end of the year.\n\nア．Of the 108.4 million forcibly displaced people＊1, 35.3 million were refugees who were forced to flee their countries. 62.5 million were internally displaced persons （IDPs）＊2, individuals displaced within the borders of their own countries. The remaining people were asylum-seekers＊3 and others in need of international protection.\n\nイ．At the end of 2022, 52 per cent of all refugees and other people in need of international protection came from just three countries: Syria （6.5 million）, Afghanistan （5.7 million）, and Mexico （5.6 million）.\n\nウ．Low- and middle-income countries hosted 76 per cent of the world’s refugees and other people in need of international protection. The Least Developed Countries provided asylum to 20 per cent of the total.\n\nエ．The United States of America hosted nearly 3.6 million refugees, the largest population worldwide, followed by Germany with 3.4 million.\n\n（注）\n\n＊1 forcibly displaced people：強制移住者\n\n＊2 internally displaced persons （IDPs）：国内避難民\n\n＊3 asylum-seekers：庇護希望者",
