      "ウ": "イの事件受理には補完性による制約がある。またエと異なり、安保理はテロ事件に関連して平和に対する脅威を認定できる。",
      "エ": "ウのように、非国際的武力紛争での共通第3条の重大な違反は、戦争犯罪として処罰の対象となりうる。オは引き渡すか訴追に付すかという条約上の義務と刑法第4条の2に対応する。",
      "オ": "オはテロ関係条約における引渡し又は訴追の原則に合う。エは安保理がテロ関連の事案にも国連憲章第7章の権限を行使できる点を見落としている。"
