    "question": "国際紛争の平和的処理に関するア～エの記述のうち、妥当なもののみを全て挙げているのはどれか。\n\nア．In several previous decisions, the International Court of Justice has held that the Court may indicate provisional measures only if the provisions relied on by the Applicant appear, prima facie, to afford a basis on which its jurisdiction could be founded.\nイ．In the Certain Norwegian Loans case＊1, the International Court of Justice held that where one of the parties to a dispute, in a declaration recognizing the jurisdiction of the Court as compulsory, makes a reservation excluding from the jurisdiction of the Court disputes concerning matters which the party determines to be within its own domestic jurisdiction, such reservation is invalid.\nウ．In the Island of Palmas case＊2, the Arbitrator held that in the judicial settlement of international territorial disputes, the earlier discovery of the disputed land by either party to the dispute shall, by itself, constitute a continuously valid territorial title to that land, regardless of subsequent developments in international law.\nエ．Under the WTO Agreement＊3, even if a Member refers a dispute to the Dispute Settlement Body concerning the issue of a breach by another Member of its obligations under the Agreement, a panel to review the dispute cannot be established unless a majority of the Members, including the Respondent, agree to establish the panel.\n\n（注）\n＊1 Certain Norwegian Loans case：International Court of Justice, Case of Certain Norwegian Loans （France v. Norway）, Judgment of 6 July 1957\n＊2 Island of Palmas case：Permanent Court of Arbitration, Island of Palmas （or Miangas） （The Netherlands / The United States of America）, Award of 4 April 1928\n＊3 WTO Agreement：Marrakesh Agreement Establishing the World Trade Organization, adopted on 15 April 1994",
