    "difficulty": 3,
    "question": "海外部門の存在しない以下のマクロ経済モデルを考える。\n\nY = C + I + G\nC = 50 + 0.75Y\nI = 200 − 1000r\nM/P = 100 + 0.25Y − 1000r\n（Y：国民所得、C：消費、I：投資、G：政府支出、r：利子率\nM：名目貨幣残高、P：物価水準）\n\nここで、G = 100、P = 1、M = 350とする。\nいま、財政政策に伴って政府支出Gが30だけ増加したとする。このとき、クラウディングアウトによる投資Iの減少分として最も妥当なのはどれか。",
