      "ウ": "明治政府は、箱館の五稜郭を拠点に抵抗を続けた榎本武揚らを降伏させると、北海道の開発を目的として開拓使を置いた。開拓使は、日露戦争が終結するまで、官営工場の設立、鉄道の敷設、炭鉱の開発などを推進する役割を担った。日露戦争の講和条約であるポーツマス条約では、樺太の全土が日本の領土となったが、第二次世界大戦の際にソ連によって占拠され、戦後、日本はサンフランシスコ平和条約に調印した結果、領有を放棄した。",
