    "difficulty": 3,
    "question": "次は、推論に関する記述であるが、Ａ～Ｄに当てはまるものの組合せとして最も妥当なのはどれか。ただし、Ｂには、㋐又は㋑のいずれかが入り、Ｄには、㋒又は㋓のいずれかが入る。\n\n推論とは、前提から結論を導く思考である。様々な研究から、人は推論課題において頻繁に論理や確率規則に違反することが示されている。こうした思考のエラーの傾向を思考のバイアスと呼ぶ。\n\n［Ａ］推論における三段論法では、「（前提1 ）全てのＸはＹである」、「（前提2 ）全てのＹはＺである」、「（結論）よって全てのＸはＺである」というように二つの前提から一つの結論を導く。その結論の妥当性は［Ｂ］。J．St．B．T．エヴァンズら（1983）は、三段論法の論理的な妥当性と、結論自体の信ぴょう性とを操作し、結論の妥当性の判断を実験参加者に求めた。その結果、論理的には妥当でないが結論に信ぴょう性がある場合に、その結論は妥当であると判断されがちである一方で、論理的には妥当であるが結論に信ぴょう性がない場合には、結論が非妥当であると判断されがちであった。このように、結論が信じられるかどうかが三段論法の妥当性判断に影響する現象を［Ｃ］と呼ぶ。\n\nその他の［Ａ］推論については、4枚カード問題（ウェイソン選択課題）により条件推論が検討されてきた。カードの裏表に書かれたアルファベットと数値との関係に関する規則を尋ねたこの問題の正答率は、低くなる傾向にあった。多くの実験参加者が［Ｄ］ことが、その原因である。ただし、問題の内容を具体的にすると、正答率が上昇することも知られている。\n\nＢの候補\n㋐：推論の形式に依存し、Ｘ、Ｙ、Ｚの内容には依存しない\n㋑：推論の形式及びＸ、Ｙ、Ｚの内容に依存する\n\nＤの候補\n㋒：規則の反証を求める一方で規則の確証を求めなかった\n㋓：規則の確証を求める一方で規則の反証を求めなかった",
    "choices": {
      "ア": "演繹／㋐／信念バイアス／㋓",
      "イ": "演繹／㋐／確証バイアス／㋒",
      "ウ": "演繹／㋑／確証バイアス／㋓",
      "エ": "帰納／㋐／信念バイアス／㋒",
      "オ": "帰納／㋑／確証バイアス／㋓"
    },
    "answer": "ア",
    "officialAnswerNumber": 1,
    "explanation": "三段論法は形式の妥当性を問う演繹推論である。結論の信じやすさの影響は信念バイアス、4枚カード問題で反証を見落とす行動は㋓に当たる。",
    "choiceExplanations": {
      "ア": "三段論法は形式の妥当性を問う演繹推論である。結論の信じやすさの影響は信念バイアス、4枚カード問題で反証を見落とす行動は㋓に当たる。",
      "イ": "ＡとＢは合う。信じやすい結論を妥当と見なすのは信念バイアスであり、4枚カード問題では反証カードを見落とすことが多い。",
      "ウ": "演繹推論の論理的妥当性を決めるのは推論の形式である。結論の信ぴょう性が判断に影響する現象は信念バイアスと呼ぶ。",
      "エ": "Ｂの㋐とＣの信念バイアスは合う。三段論法は演繹推論で、選択課題の典型的な誤りでは確証を探して反証を見落とす。",
      "オ": "4枚カード問題での傾向を示す㋓は合う。三段論法は演繹推論で、その妥当性は各項の具体的内容によらず形式で決まる。"
    },
