    "difficulty": 3,
    "question": "多様な教育的ニーズに応じた支援に関する記述Ａ～Ｄのうち、妥当なもののみを挙げているのはどれか。\n\nＡ．自閉スペクトラム症＊1（ASD）は、文部科学省の手引＊2によると、他者との社会的関係の形成の困難さ、言葉の発達の遅れ、興味や関心が狭く特定のものにこだわることを特徴としている。また、認知の特性として、視覚的な情報を処理するよりも、聴覚的な情報を処理する方が得意な「聴覚認知の優位」が挙げられることから、言葉で段取りを説明したり、九九や英単語を教えるときには暗唱しながら教えたりすることが効果的であるとされている。\nＢ．注意欠如多動症＊1（ADHD）は、文部科学省の手引によると、身の回りの特定のものに意識を集中させる脳の働きである注意力に問題があり、又は、衝動的で落ち着きのない行動により、生活上、様々な困難に直面している状態をいう。注意や叱責を重ねるよりも、望ましい行動を具体的に示したり、行動の良い面を見つけたらすぐに褒めたりすることも効果的であるとされている。\nＣ．文部科学省の調査＊3によると、令和3年5月現在、日本語指導が必要な児童生徒は増加傾向にあるが、その受入れに際しての指導体制を整備しているとする地方公共団体は全体の約5割である。我が国では、国籍を問わず学校等において日本語教育を含めた適切な教育の機会を提供するため教職員の配置に係る制度の整備等が図られているほか、外国籍の児童生徒の就学機会確保のために地方公共団体が講ずべき事項についても指針として定められている。\nＤ．特定分野に特異な才能のある児童生徒は、その特性のために学習や学校生活に困難を抱える場合があるとされており、このような児童生徒への支援として、我が国では中学校から高等学校への飛び入学が制度化され、複数の学校で導入されている。しかし、このような「早修」は学習内容の体系性を損なうおそれがあるため慎重な運用が求められており、対象とする児童生徒については知能指数（IQ）などの数値や特定の基準により選抜することと定められている。\n\n＊1 DSM‒5‒TR（精神疾患の診断・統計マニュアル）の表記による。\n＊2 「障害のある子供の教育支援の手引～子供たち一人一人の教育的ニーズを踏まえた学びの充実に向けて～」（令和3年6月）＊3 「日本語指導が必要な児童生徒の受入状況等に関する調査（令和3年度）」",
