    "difficulty": 3,
    "question": "次の決定論・非決定論に関する文章に示された問題をめぐる記述として最も妥当なのはどれか。\n\n決定論とは、すべての出来事は生じるか生じないかが先行する出来事によって完全に決定されている、という主張である。そうだとすると、ただ一つの未来が過去によって決定されており、偶然的なものは存在しえない。したがって、意志決定のための複数の選択肢が前提される自由意志は、その存在が否定される。\nしかし、もしも決定論のいうように、意志決定の自由が存在せず、すべての行為が因果的に必然化されているのならば、行為に対する人間の責任がすべて解除されることにならないか。ここに、自由な行為の余地を求めて人間の意志決定を特別視し、自由な選択を可能にする何らかの意味での事前の非決定性を意志の働きに認めようとする、非決定論が唱えられる理由がある。",
