      "イ": "ルネサンスは、狭義には14～15世紀の西ヨーロッパにおけるギリシア・ローマの知的文化を復興する運動を指すが、そのような試みは中世初期から断続的になされてきた。カロリング朝期のフランク王国では、聖職者育成を目的として古典言語の運用能力向上が図られ、オウィディウスやウェルギリウスなどのアテネ盛期の作品が書写された。12世紀には、トレドやシチリアでギリシア・ローマの学術書がフランス語や英語に翻訳された。",
      "ウ": "中世初期の西ヨーロッパでは修道院が学術や教育といった知的活動を担っていたが、その後、複数の司教座都市で学校が開かれるなど変化の芽が生じた。これに続き、教師と学生が各地に大学を結成した。パリ大学とオックスフォード大学は神学、サレルノ大学は医学、ボローニャ大学は法学に関する研究と教育を特徴とし、聖職者、医師、官僚や法律家の育成を担った。教皇や国王は、大学設立の動きを保護した。",
