      "イ": "19世紀半ば、フランスやドイツは、工業化のための起爆剤として鉄道の建設を進め、その建設需要から製鉄業が発展した。近隣のオランダやベルギーでは、鉄道に加えて運河網も整備された。南北戦争直前に最初の大陸横断鉄道が開通するなど、アメリカ大陸各地で交通網の整備が進んだことにより、カナダやラテンアメリカ諸国では工業生産を主軸とした経済が発展した。",
      "ウ": "スエズ運河は、19世紀後半にフランス人技師オスマンにより建設が進められた。その後、この運河は20世紀半ばまでイギリスの管理下に置かれたが、ナセル政権下のエジプトにより国有化された。パナマ運河についても計画当初はフランスが関与していたが、その後、セオドア=ローズヴェルト大統領の孤立主義的な外交政策の下、アメリカの経済的権益と深い関わりを持つようになった。",
      "エ": "20世紀初頭のアメリカでは、フォード社が、部品の規格化と流れ作業方式による生産体制の革新に成功し、Ｔ型車に代表される自動車の大量生産時代が幕を開けた。このような生産方式を特徴とする経営理念はフォーディズムの名で知られる。一方、後発のジェネラル= モーターズ社は、多様な車種をそろえる戦略を展開することで、急成長を果たした。",
