      "イ": "読本（よみほん）は浮世草子に交代する形で出現し、中国の白話小説などを典拠に本格的な読み物として成長を遂げた。江戸時代前期には上方で瀧澤（曲亭）馬琴が『雨月物語』を著し、後期には江戸で上田秋成が『南総里見八犬伝』を著している。『雨月物語』は短・中編から成る幻想的な怪異小説集であり、『南総里見八犬伝』は保元の乱に敗れた源為朝が大島に配流され、更に琉球に渡って活躍する物語である。",
      "ウ": "江戸時代中期から後期にかけて出現した黄表紙は、それまでの草双紙から絵を排除し、文章を主体にした小説ジャンルで、恋川春町の『国性爺合戦』をはじめ、多くは儒教の道徳観に基づいた勧善懲悪を主題としている。これに対し、江戸時代後期の滑稽本は庶民の生き様をユーモラスに描いた小説ジャンルで、山東京伝の『東海道中膝栗毛』や『浮世風呂』などが知られている。",
      "エ": "天保の改革で厳しい言論統制が敷かれ、キリスト教の布教に関する洋書には過酷な弾圧が行われたが、戯作に関しては比較的統制は緩やかであった。そのため奢侈、贅沢を禁じられた庶民はそのはけ口を戯作に求め、人情本と呼ばれる恋愛小説が全盛時代を迎えた。人情本の代表作としては、『源氏物語』のパロディである、為永春水の『金々先生栄花夢』などがある。",
      "オ": "明治の文明開化によって江戸戯作は衰退し、急速に読者を失っていった。坪内逍遙は『小説神髄』を著し、西洋の「ノベル」よりも「ロマン」の系譜こそが小説の進むべき道であるとし、世態風俗の正確な模写の重要性を説いた。『五重塔』はその実践作で、下級官吏の内海文三が下宿の娘、お勢と恋仲になるものの失職し、処世術に長けた元同僚に恋人を奪われていく物語である。"
