      "ア": "J．H．チューネンは、代表的著書『農業生産立地理論』において、自然条件の差異を考慮しない均質空間を前提とし、市場である都市を中心に、そこからの距離に応じて作物・農業経営様式が同心円状に展開していくとした。この農業立地の有様は、その後の都市化や輸送技術の進展により変容するものの、併せて示された都市からの距離が離れるほど右上がりとなる地代曲線モデルは、都市の地代モデルに援用されている。",
      "イ": "A．ウェーバーは、工業の立地において、輸送や労働など生産に関わる費用が最小となるよう指向される点を理論化した。特に本理論は、原料産地、原料と製品の重量関係、労働集約型か否かなどによって、業種ごとの工業の立地傾向を示し得ることを特色とする。例えば、輸送費に着目すると、原料の重量が製品の重量より小さい場合、原料産地に近いところに立地する。これは鉄鋼業など普遍原料に依拠する工業に特徴的とされる。",
      "ウ": "D．ハーヴェイは、古典的立地論の影響を強く受けつつ、1950～1960年代にかけてアメリカやイギリスで盛んになっていく計量地理学の理論的支柱となった『都市と社会的不平等』を出版した。この中で、先行立地する企業の生産活動を通して需要が発生し、それが更なる立地を促すという累積的循環過程を生成するとともに、中心－周辺関係の地域形成パターンを確立・強化することを示した。",
      "エ": "W．クリスタラーは、都市を様々な財の供給がなされる中心機能が立地する場所として捉え、その空間的配置に関する理論を構築した。財の到達範囲という点から、上限を消費者側が到達し得る範囲、下限を供給側が経営を維持し得る範囲とし、この上限を基に、最小中心地数での全域への供給システムを提示した。彼の理論は、ナチス政権下のドイツの国土整備構想に取り入れられた。",
