      "ア": "宗教は極めて複雑な現象であり、過去に多様な定義がなされてきた。E．タイラーが宗教の最小限の定義として提唱した「霊的存在への信仰」は、文化人類学における宗教の基本的、歴史的な定義ともいわれている。彼は、宗教の原初形態としてトーテミズムを想定し、社会の進化に伴い神霊の役割が整理され、最終的には多神教に到達するという図式を提示した。",
      "イ": "宗教についてはいくつかの分類や類型化の試みがなされてきた。世界宗教と民族宗教の分類もその一つである。世界宗教とは、キリスト教やイスラム教、仏教に代表される世界的な分布を示す宗教である。これに対し、民族宗教は特定の民族、地縁・血縁、地域を基盤として外部には広がりにくい傾向を持つ宗教であり、日本の神道はその代表的な例として挙げられる。",
