    "difficulty": 3,
    "question": "欲求や動機づけに関する記述ア～エのうち、妥当なもののみを全て挙げているのはどれか。\n\nア．A．H．マズローの欲求階層説では、下位の欲求が満たされると上位へ進むと仮定されている。欲求は三層に分けられ、下層の欲求は一次的欲求である安全・安定の欲求、中層の欲求は、愛情、所属、承認、自尊の欲求、上層の欲求は最も高次な欲求である自己実現の欲求である。\nイ．「賞や罰によって学習活動を指導する」という教育観は、認知心理学の視点によって子どもを学習へと動機づけるものである。一方で、「子どもが既にもっている知識と新しい知識を結び付けるよう指導する」という教育観は、観察学習の視点によって子どもを学習へと動機づけるものである。\nウ．個人の中に、相反するあるいは両立し得ない衝動や欲求などが存在するとき、どの行動を取ればよいか選択できない心的状態を葛藤という。K．レヴィンの葛藤の分類には、複数の対象が同じくらいの正の誘意性をもつ「接近－接近の葛藤」、同じくらいの負の誘意性をもつ「回避－回避の葛藤」、同一の対象が相反する誘意性をもつ「接近－回避の葛藤」がある。\nエ．B．ワイナーの帰属理論では、失敗の原因を努力不足に帰属した場合の方が、能力不足に帰属した場合よりも失敗による負の影響が大きく、後の行動が起こらなくなるとされる。また、この理論には、自身の成功や失敗の原因が時間的に安定したものなのか、不安定なものなのかを意味する「統制の位置」という次元がある。",
    "choices": {
      "ア": "ア",
      "イ": "ウ",
      "ウ": "ア、イ",
      "エ": "イ、エ",
      "オ": "ウ、エ"
    },
