    "difficulty": 3,
    "question": "次は、記憶に関する記述であるが、Ａ～Ｅに当てはまるものの組合せとして最も妥当なのはどれか。\n\n心理学における最初の本格的な記憶研究は、H．エビングハウスによって行われ、その研究成果は1885年に発表された。彼が記憶研究を行う契機になったのは、G．T．フェヒナーの『［Ａ］』（1860）に影響を受けたことであった。彼は、G．T．フェヒナーのアイディアを引き継ぎ、記憶の科学的探求を開始した。\n\nH．エビングハウスは、純粋な記憶のプロセスを調べるために、「WUX」といった無意味綴りを考案した。そして、この無意味綴りのリストを完全に覚えるまでの時間を測定し、次に任意の時間経過後に再びそのリストを完全に覚えるのに必要な時間を測定した。この［Ｂ］と呼ばれる方法を用いて、\n\n［Ｃ］ = （［Ｄ］に必要な学習時間 − ［Ｅ］に必要な学習時間）／［Ｄ］に必要な学習時間 × 100\n\nという［Ｃ］に関する公式を導き出し、記憶を数量的に把握できるようにした。この研究は、記憶のプロセスを捉えた画期的なものであった。",
