    "question": "教育におけるジェンダーに関する記述として最も妥当なのはどれか。\n\n＊1世界経済フォーラム（WEF）が各国における男女格差を測る指数として公表しているもの。この指数は、男性に対する女性の割合（女性の数値／男性の数値）を示しており、0が完全不平等、1が完全平等を示すとされている。\n＊2 「小学校」、「中学校・義務教育学校」、「高等学校・中等教育学校」、「特別支援学校」の別",
