    "question": "我が国における子供や若者の状況に関する記述Ａ～Ｄのうち、妥当なもののみを挙げているのはどれか。\n\nＡ．子供の貧困問題への対応については、昭和60年に「子どもの貧困対策の推進に関する法律」が成立し、施行に伴い設置されたこども家庭庁において対策が進められてきた。その後、生活保護を受給する母子世帯数の減少など対策の成果が認められ、同法の目的が達成されたことから、令和4年に同法は廃止された。貧困の状態にある子供の就学援助等残された課題については「こども基本法」に引き続き対策を行うことが定められている。\nＢ．子供のいる世帯のうち、ひとり親家庭の世帯においては子供の大学進学率が他の世帯と比べて低い状況にある。そのため、家庭の経済状況等によって子供の進路の選択肢の幅が狭まることのないよう、内閣府及び文部科学省は、高等教育段階における取組として、独立行政法人日本学生支援機構が実施する貸与型奨学金や、各大学が実施する授業料等減免への支援を行っている。\nＣ．「令和3年度子供の学習費調査」（文部科学省）の結果によると、世帯の年間収入別学校外活動費＊は、幼稚園、小学校、中学校、高等学校（全日制）において、公立、私立ともに世帯の年間収入が増加しても支出額はほぼ一定であることが分かった。また、学校が所在する市区町村の人口規模別にみた支出状況では、公立小・中学校では「10万人未満」よりも「100万人以上・特別区」の方が、各家庭における学校外活動費の支出は少ない。\nＤ．厚生労働省は、15～49歳の若年無業者に対して、全ての都道府県に設置されている地域若者サポートステーション（サポステ）において、職場見学や職場体験、就職した者への定着・ステップアップ相談等のサービスを実施している。また、ひきこもりの状態にある者やその家族への支援策として、平成30年度には全ての都道府県及び指定都市に、ひきこもり地域支援センターの設置が完了した。\n\n＊ 自宅学習や学習塾・家庭教師、体験活動や習い事などの経費",
